// Public, CSS-free Sass API.
// Components import it with `@use 'styles' as vz;`.
@forward 'tokens/color';
@forward 'tokens/space';
@forward 'tokens/type';
@forward 'tokens/radius';
@forward 'tokens/shadow';
@forward 'tokens/motion';
@forward 'tokens/z';
@forward 'tokens/breakpoints';
@forward 'mixins/focus-ring';
@forward 'mixins/interaction';
@forward 'mixins/surface';
@forward 'mixins/truncate';
@forward 'mixins/scrollbar';
@forward 'mixins/icon';
@forward 'mixins/supports';
@forward 'mixins/group';

@use '../tokens/color' as color;

@layer base {
  body {
    margin: 0;
    min-height: 100vh;
    background: color.color('background');
    color: color.color('foreground');
    font-family:
      -apple-system,
      BlinkMacSystemFont,
      'SF Pro Text',
      'SF Pro Display',
      'Segoe UI',
      Roboto,
      Helvetica,
      Arial,
      sans-serif;
    font-size: 1rem;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizelegibility;
  }

  ::selection {
    background: color.color('primary', 0.2);
    color: color.color('foreground');
  }

  :where(button, input, select, textarea) {
    font: inherit;
  }
}

// Accessibility primitives shared by every component.
.vz-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border-width: 0;
}

.vz-sr-only-focusable:not(:focus, :focus-within) {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border-width: 0;
}

// Global safety net for visitors who ask for less motion.
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

// Minimal, predictable reset. Kept in `@layer base` so component styles
// (unlayered) always win without specificity tricks.
@use '../tokens/color' as color;

@layer base {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
    border-width: 0;
    border-style: solid;
    border-color: color.color('border');
  }

  html {
    text-size-adjust: 100%;
    scroll-behavior: smooth;
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6,
  p,
  blockquote,
  dl,
  dd,
  figure,
  pre {
    margin: 0;
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    font-size: inherit;
    font-weight: inherit;
  }

  ul,
  ol {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  img,
  svg,
  video,
  canvas {
    display: block;
  }

  img,
  video {
    max-width: 100%;
    height: auto;
  }

  button {
    background: none;
    cursor: pointer;
  }

  a {
    color: inherit;
    text-decoration: inherit;
  }

  table {
    border-collapse: collapse;
    border-color: inherit;
  }
}

// Application stylesheet entry. Import once, before the app renders.
@use 'index' as vz;
@use 'base/reset';
@use 'base/base';
@use 'base/globals';

// ── Themes ────────────────────────────────────────────────
@include vz.emit-color-tokens(':root', 'light');
@include vz.emit-color-tokens('.dark', 'dark');
@include vz.emit-raw-color-tokens(':root');

// ── Scales ────────────────────────────────────────────────
@include vz.emit-space-tokens(':root');
@include vz.emit-type-tokens(':root');
@include vz.emit-radius-tokens(':root');
@include vz.emit-shadow-tokens(':root', 'light');
@include vz.emit-shadow-tokens('.dark', 'dark');
@include vz.emit-motion-tokens(':root');
@include vz.emit-z-tokens(':root');

@use '../tokens/color' as color;

/// Visible keyboard focus. Outline follows `border-radius` in every supported
/// browser and does not consume layout space.
///
/// @param {Number} $width [2px] - Outline width
/// @param {Number} $offset [2px] - Gap between element and outline
/// @param {Number} $alpha [0.6] - Ring opacity
/// @param {String} $token ['ring'] - Colour token
@mixin focus-ring($width: 2px, $offset: 2px, $alpha: 0.6, $token: 'ring') {
  &:focus-visible {
    outline: $width solid color.color($token, $alpha);
    outline-offset: $offset;
  }
}

/// Cross-module state hooks.
///
/// CSS Module names are hashed, so marker classes cannot work. Components mark
/// a parent with `data-group` / `data-peer`; attributes are never hashed.

@mixin group-hover {
  @media (hover: hover) and (pointer: fine) {
    [data-group]:hover &,
    [data-group][data-state='open'] & {
      @content;
    }
  }
}

@mixin group-focus {
  [data-group]:focus-within & {
    @content;
  }
}

@mixin group-state($state) {
  [data-group][data-state='#{$state}'] & {
    @content;
  }
}

@mixin peer-focus {
  [data-peer]:focus-visible ~ & {
    @content;
  }
}

@mixin peer-checked {
  [data-peer]:checked ~ & {
    @content;
  }
}

@use '../tokens/space' as space;

/// Normalise an inline SVG icon.
///
/// @param {Number|String} $size [4] - A spacing step
@mixin icon($size: 4) {
  flex: none;
  width: space.space($size);
  height: space.space($size);
}

/// Hover that only fires on devices with a real pointer.
@mixin hover {
  @media (hover: hover) and (pointer: fine) {
    &:hover {
      @content;
    }
  }
}

/// Pressed state.
@mixin active {
  &:active {
    @content;
  }
}

/// Disabled for native controls and ARIA-disabled elements.
@mixin disabled {
  &:disabled,
  &[aria-disabled='true'] {
    @content;
  }
}

/// Selected state shared by tabs, listboxes, and segmented controls.
@mixin selected {
  &[aria-selected='true'],
  &[data-state='selected'] {
    @content;
  }
}

/// Placeholder text for inputs and textareas.
@mixin placeholder {
  &::placeholder {
    @content;
  }
}

@use '../tokens/color' as color;

/// Slim, theme-aware scrollbar.
///
/// @param {String} $size ['10px'] - Thickness
@mixin scrollbar($size: 10px) {
  scrollbar-width: thin;
  scrollbar-color: color.color('muted-foreground', 0.4) transparent;

  &::-webkit-scrollbar {
    width: $size;
    height: $size;
  }

  &::-webkit-scrollbar-track {
    background: transparent;
  }

  &::-webkit-scrollbar-thumb {
    background: color.color('muted-foreground', 0.35);
    border-radius: 999px;
    border: 2px solid transparent;
    background-clip: content-box;
  }

  &::-webkit-scrollbar-thumb:hover {
    background: color.color('muted-foreground', 0.55);
    background-clip: content-box;
  }
}

/// Prevent scroll chaining behind an overlay.
@mixin overscroll {
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
}

/// Progressive enhancement gate.
///
/// @param {String} $feature - A declaration, e.g. `color: oklch(0% 0 0)`
@mixin supports($feature) {
  @supports (#{$feature}) {
    @content;
  }
}

/// Fallback-first helper.
///
/// @param {String} $property - CSS property
/// @param {String} $fallback - Universally supported value
/// @param {String} $modern - Enhancement value
@mixin progressive($property, $fallback, $modern) {
  #{$property}: $fallback;
  #{$property}: $modern;
}

@use '../tokens/color' as color;
@use '../tokens/radius' as radius;
@use '../tokens/shadow' as shadow;

/// A layered card surface.
///
/// @param {Number} $level [1] - Elevation 1–3
@mixin surface($level: 1) {
  background: color.color('card');
  color: color.color('card-foreground');
  border: 1px solid color.color('border');
  border-radius: radius.radius('xl');
  box-shadow: shadow.elevation($level);
}

/// A surface above the page (popover, dropdown, sheet).
@mixin raised($level: 2) {
  @include surface($level);

  background: color.color('popover');
  color: color.color('popover-foreground');
}

/// A recessed area for code blocks, wells, and inline groups.
@mixin inset {
  background: color.color('muted');
  color: color.color('foreground');
  border: 1px solid color.color('border');
  border-radius: radius.radius('md');
}

/// Single-line ellipsis.
@mixin truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/// Multi-line clamp.
///
/// @param {Number} $lines [2] - Maximum visible lines
@mixin line-clamp($lines: 2) {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: $lines;
  line-clamp: $lines;
}

@use 'sass:map';

/// Viewport breakpoints. Prefer container queries for reusable components.
$breakpoints: (
  'sm': 40rem,
  'md': 48rem,
  'lg': 64rem,
  'xl': 80rem,
  '2xl': 96rem,
) !default;

@function breakpoint-value($name) {
  @if not map.has-key($breakpoints, $name) {
    @error 'Unknown breakpoint `#{$name}`. Use one of: #{map.keys($breakpoints)}.';
  }

  @return map.get($breakpoints, $name);
}

@mixin up($name) {
  @media (min-width: breakpoint-value($name)) {
    @content;
  }
}

@mixin down($name) {
  @media (max-width: calc(#{breakpoint-value($name)} - 0.02px)) {
    @content;
  }
}

@mixin between($lower, $upper) {
  @media (min-width: breakpoint-value($lower)) and (max-width: calc(#{breakpoint-value($upper)} - 0.02px)) {
    @content;
  }
}

@mixin container-up($size, $name: null) {
  @if $name {
    @container #{$name} (min-width: #{$size}) {
      @content;
    }
  } @else {
    @container (min-width: #{$size}) {
      @content;
    }
  }
}

@use 'sass:map';
@use 'sass:string';

/// Colour tokens — the single source of truth for theming.
///
/// Values are HSL *triplets* (`220 18% 97%`) so alpha can be applied without
/// `color-mix()`: `color('primary', .9)` emits `hsl(var(--primary) / 0.9)`.
/// Keep the triplet format when adding a token, and add it to both maps.
$light: (
  'background': '220 18% 97%',
  'foreground': '222 47% 11%',
  'card': '0 0% 100%',
  'card-foreground': '222 47% 11%',
  'popover': '0 0% 100%',
  'popover-foreground': '222 47% 11%',
  'primary': '217 91% 46%',
  'primary-foreground': '0 0% 100%',
  'secondary': '213 36% 95%',
  'secondary-foreground': '215 28% 17%',
  'muted': '216 22% 95%',
  'muted-foreground': '221 13% 44%',
  'accent': '216 24% 96%',
  'accent-foreground': '215 28% 17%',
  'destructive': '4 74% 49%',
  'destructive-foreground': '0 0% 100%',
  'success': '155 90% 24%',
  'success-foreground': '0 0% 100%',
  'info': '199 89% 48%',
  'warning': '38 92% 50%',
  'border': '218 17% 91%',
  'input': '219 14% 60%',
  'ring': '217 91% 46%',
  'code-bg': '222 47% 11%',
  'code-fg': '210 40% 98%',
  'code-border': '215 28% 27%',
  'code-muted': '215 16% 65%',
) !default;

$dark: (
  'background': '240 2% 6%',
  'foreground': '0 0% 98%',
  'card': '240 2% 10%',
  'card-foreground': '0 0% 98%',
  'popover': '240 2% 13%',
  'popover-foreground': '0 0% 98%',
  'primary': '211 100% 58%',
  'primary-foreground': '240 2% 7%',
  'secondary': '240 2% 16%',
  'secondary-foreground': '0 0% 93%',
  'muted': '240 2% 13%',
  'muted-foreground': '240 2% 66%',
  'accent': '240 2% 17%',
  'accent-foreground': '0 0% 98%',
  'destructive': '3 100% 65%',
  'destructive-foreground': '240 2% 7%',
  'success': '135 65% 58%',
  'success-foreground': '240 2% 7%',
  'info': '199 100% 62%',
  'warning': '36 100% 58%',
  'border': '240 2% 20%',
  'input': '240 2% 30%',
  'ring': '211 100% 65%',
  'code-bg': '240 2% 5%',
  'code-fg': '0 0% 98%',
  'code-border': '240 2% 20%',
  'code-muted': '240 2% 66%',
) !default;

/// Tokens whose value is already a complete colour. Shared by both themes.
$raw: (
  'shadow-color': '220 43% 11%',
) !default;

/// Read a colour token as a runtime CSS variable.
///
/// @param {String} $name - Key from `$light`, e.g. `primary`
/// @param {Number} $alpha [1] - Opacity from 0 to 1
/// @return {String} e.g. `hsl(var(--primary) / 0.9)`
/// @example scss
///   background: vz.color('primary', .9);
@function color($name, $alpha: 1) {
  @if not map.has-key($light, $name) {
    @error 'Unknown color token `#{$name}`. Add it to tokens/_color.scss (both themes).';
  }

  @return string.unquote('hsl(var(--#{$name}) / #{$alpha})');
}

/// Emit theme custom properties.
///
/// @param {String} $selector [':root'] - Where to emit
/// @param {String} $mode ['light'] - `light` or `dark`
@mixin emit-color-tokens($selector: ':root', $mode: 'light') {
  $values: $light;
  $scheme: light;

  @if $mode == 'dark' {
    $values: $dark;
    $scheme: dark;
  }

  #{$selector} {
    color-scheme: #{$scheme};

    @each $name, $value in $values {
      --#{$name}: #{$value};
    }
  }
}

/// Emit tokens shared by both themes.
@mixin emit-raw-color-tokens($selector: ':root') {
  #{$selector} {
    @each $name, $value in $raw {
      --#{$name}: #{$value};
    }
  }
}

@use 'sass:map';
@use 'sass:string';

/// Motion tokens. Components should opt in with `motion-safe()` when adding
/// non-essential movement; the global guard handles the rest.
$durations: (
  'fast': '150ms',
  'base': '200ms',
  'slow': '300ms',
  'slower': '500ms',
) !default;

$easings: (
  'out': 'cubic-bezier(0.22, 1, 0.36, 1)',
  'in-out': 'cubic-bezier(0.4, 0, 0.2, 1)',
  'spring': 'cubic-bezier(0.34, 1.56, 0.64, 1)',
) !default;

/// @param {String} $name ['base'] - `fast`, `base`, `slow`, `slower`
@function duration($name: 'base') {
  @if not map.has-key($durations, $name) {
    @error 'Unknown duration `#{$name}`. Use one of: #{map.keys($durations)}.';
  }

  @return string.unquote('var(--duration-#{$name})');
}

/// @param {String} $name ['out'] - `out`, `in-out`, `spring`
@function ease($name: 'out') {
  @if not map.has-key($easings, $name) {
    @error 'Unknown easing `#{$name}`. Use one of: #{map.keys($easings)}.';
  }

  @return string.unquote('var(--ease-#{$name})');
}

@mixin motion-safe {
  @media (prefers-reduced-motion: no-preference) {
    @content;
  }
}

@mixin motion-reduce {
  @media (prefers-reduced-motion: reduce) {
    @content;
  }
}

@mixin emit-motion-tokens($selector: ':root') {
  #{$selector} {
    @each $name, $value in $durations {
      --duration-#{$name}: #{$value};
    }

    @each $name, $value in $easings {
      --ease-#{$name}: #{$value};
    }
  }
}

@use 'sass:map';
@use 'sass:string';

/// Continuous corner radii. Every component reads `var(--radius-*)`, so a
/// consumer can retune the whole kit by overriding these variables.
$radii: (
  'xs': 6px,
  'sm': 8px,
  'md': 10px,
  'lg': 12px,
  'xl': 16px,
  '2xl': 20px,
  '3xl': 24px,
  'full': 999px,
) !default;

/// @param {String} $name ['lg'] - Key from `$radii`
@function radius($name: 'lg') {
  @if not map.has-key($radii, $name) {
    @error 'Unknown radius `#{$name}`. Use one of: #{map.keys($radii)}.';
  }

  @return string.unquote('var(--radius-#{$name})');
}

@mixin emit-radius-tokens($selector: ':root') {
  #{$selector} {
    @each $name, $value in $radii {
      --radius-#{$name}: #{$value};
    }
  }
}

@use 'sass:map';
@use 'sass:string';

/// Restrained elevation. Dark mode swaps to deeper, softer shadows.
$light-levels: (
  '1': '0 1px 2px hsl(var(--shadow-color) / 0.06), 0 1px 1px hsl(var(--shadow-color) / 0.04)',
  '2': '0 8px 24px hsl(var(--shadow-color) / 0.08), 0 2px 6px hsl(var(--shadow-color) / 0.05)',
  '3': '0 20px 48px hsl(var(--shadow-color) / 0.12), 0 4px 10px hsl(var(--shadow-color) / 0.06)',
) !default;

$dark-levels: (
  '1': '0 1px 2px hsl(0 0% 0% / 0.35)',
  '2': '0 8px 28px hsl(0 0% 0% / 0.45)',
  '3': '0 24px 56px hsl(0 0% 0% / 0.55)',
) !default;

/// @param {Number} $level [1] - Elevation level 1–3
@function elevation($level: 1) {
  @if not map.has-key($light-levels, '#{$level}') {
    @error 'Unknown elevation `#{$level}`. Use 1, 2 or 3.';
  }

  @return string.unquote('var(--shadow-#{$level})');
}

@mixin emit-shadow-tokens($selector: ':root', $mode: 'light') {
  $levels: $light-levels;

  @if $mode == 'dark' {
    $levels: $dark-levels;
  }

  #{$selector} {
    @each $level, $value in $levels {
      --shadow-#{$level}: #{$value};
    }
  }
}

@use 'sass:map';
@use 'sass:string';

/// Spacing scale on a 4px base. Values are compile-time literals.
$space: (
  '0': 0,
  'px': 1px,
  '0.5': 0.125rem,
  '1': 0.25rem,
  '1.5': 0.375rem,
  '2': 0.5rem,
  '2.5': 0.625rem,
  '3': 0.75rem,
  '3.5': 0.875rem,
  '4': 1rem,
  '5': 1.25rem,
  '6': 1.5rem,
  '7': 1.75rem,
  '8': 2rem,
  '9': 2.25rem,
  '10': 2.5rem,
  '11': 2.75rem,
  '12': 3rem,
  '14': 3.5rem,
  '16': 4rem,
  '20': 5rem,
  '24': 6rem,
) !default;

/// Resolve a spacing step.
///
/// @param {Number|String} $step - A key from `$space`, e.g. `4`, `0.5`, `px`
/// @return {Number} e.g. `1rem`
@function space($step) {
  $key: '#{$step}';

  @if not map.has-key($space, $key) {
    @error 'Unknown space step `#{$step}`. Add it to tokens/_space.scss.';
  }

  @return map.get($space, $key);
}

/// Emit spacing variables for docs and consumer overrides.
/// Fractional steps are emitted with dashes (`--space-0-5`) because a dot is
/// not valid in a custom property name.
@mixin emit-space-tokens($selector: ':root') {
  #{$selector} {
    @each $name, $value in $space {
      $safe: '#{$name}';
      $dot: string.index($safe, '.');

      @if $dot {
        $safe: string.slice($safe, 1, $dot - 1) + '-' + string.slice($safe, $dot + 1);
      }

      --space-#{$safe}: #{$value};
    }
  }
}

@use 'sass:map';

/// Primitive type scale.
$sizes: (
  'xs': 0.75rem,
  'sm': 0.875rem,
  'base': 1rem,
  'lg': 1.125rem,
  'xl': 1.25rem,
  '2xl': 1.5rem,
  '3xl': 1.875rem,
  '4xl': 2.25rem,
  '5xl': 3rem,
) !default;

$leading: (
  'none': 1,
  'tight': 1.2,
  'snug': 1.35,
  'normal': 1.5,
  'relaxed': 1.625,
) !default;

$tracking: (
  'tight': -0.02em,
  'normal': 0,
  'wide': 0.02em,
) !default;

$weights: (
  'normal': 400,
  'medium': 500,
  'semibold': 600,
  'bold': 700,
) !default;

/// Named combinations. Keep this list short and semantic.
$presets: (
  'display': (
    size: '5xl',
    leading: 'tight',
    weight: 'bold',
    tracking: 'tight',
  ),
  'title-1': (
    size: '3xl',
    leading: 'tight',
    weight: 'bold',
    tracking: 'tight',
  ),
  'title-2': (
    size: '2xl',
    leading: 'snug',
    weight: 'semibold',
    tracking: 'tight',
  ),
  'title-3': (
    size: 'xl',
    leading: 'snug',
    weight: 'semibold',
    tracking: 'normal',
  ),
  'body': (
    size: 'base',
    leading: 'normal',
    weight: 'normal',
    tracking: 'normal',
  ),
  'body-sm': (
    size: 'sm',
    leading: 'normal',
    weight: 'normal',
    tracking: 'normal',
  ),
  'label': (
    size: 'sm',
    leading: 'none',
    weight: 'medium',
    tracking: 'normal',
  ),
  'label-sm': (
    size: 'xs',
    leading: 'none',
    weight: 'medium',
    tracking: 'normal',
  ),
  'caption': (
    size: 'xs',
    leading: 'tight',
    weight: 'medium',
    tracking: 'wide',
  ),
) !default;

/// Read one step from the type scale.
///
/// @param {String} $name - Key from `$sizes`, e.g. `sm`
@function font-size($name: 'base') {
  @if not map.has-key($sizes, $name) {
    @error 'Unknown font size `#{$name}`. Use one of: #{map.keys($sizes)}.';
  }

  @return map.get($sizes, $name);
}

/// Emit a full type preset.
///
/// @param {String} $name ['body'] - Key from `$presets`
@mixin text($name: 'body') {
  @if not map.has-key($presets, $name) {
    @error 'Unknown text preset `#{$name}`. Use one of: #{map.keys($presets)}.';
  }

  $preset: map.get($presets, $name);

  font-size: map.get($sizes, map.get($preset, size));
  line-height: map.get($leading, map.get($preset, leading));
  font-weight: map.get($weights, map.get($preset, weight));
  letter-spacing: map.get($tracking, map.get($preset, tracking));
}

/// Emit font-size variables for docs.
@mixin emit-type-tokens($selector: ':root') {
  #{$selector} {
    @each $name, $value in $sizes {
      --text-#{$name}: #{$value};
    }
  }
}

@use 'sass:map';
@use 'sass:string';

/// One ladder for every stacking context.
$layers: (
  'base': 0,
  'dropdown': 1000,
  'sticky': 1100,
  'overlay': 1200,
  'modal': 1300,
  'popover': 1400,
  'toast': 1500,
  'tooltip': 1600,
) !default;

/// @param {String} $name ['base'] - Layer name from `$layers`
@function z($name: 'base') {
  @if not map.has-key($layers, $name) {
    @error 'Unknown z layer `#{$name}`. Use one of: #{map.keys($layers)}.';
  }

  @return string.unquote('var(--z-#{$name})');
}

@mixin emit-z-tokens($selector: ':root') {
  #{$selector} {
    @each $name, $value in $layers {
      --z-#{$name}: #{$value};
    }
  }
}
